1	// Package deploy generates Kubernetes deployment manifests (a kustomize
2	// base + overlays tree) for a previously scaffolded integration. It reads
3	// the committed .intropy/scaffold.json record, re-fetches the exact
4	// blueprint version it pins, and renders the blueprint's manifests/
5	// directory with the blueprint package's template machinery.
6	package deploy
7	
8	import (
9		"context"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"io"
14		"net/http"
15		"os"
16		"path/filepath"
17	
18		"github.com/integrio-intropy/intropy-cli/internal/blueprint"
19	)
20	
21	const (
22		// manifestDirName is the directory inside a blueprint (next to
23		// skeleton/) that holds the deployment manifest template:
24		// <blueprint>/manifests/template.yaml + <blueprint>/manifests/skeleton/.
25		manifestDirName = "manifests"
26	
27		templateManifestName = "template.yaml"
28		skeletonDirName      = "skeleton"
29	
30		// scaffoldValuesKey is the reserved key under which the full scaffold
31		// value map is exposed to manifest templates ({{ .scaffold.name }}).
32		scaffoldValuesKey = "scaffold"
33	
34		// defaultOutputDirName is the output directory relative to the project
35		// root when --output is not given.
36		defaultOutputDirName = "deploy"
37	)
38	
39	type CreateOptions struct {
40		StartDir   string // directory to begin the scaffold.json walk-up from; default "."
41		OutputDir  string // default <projectRoot>/deploy
42		Version    string // blueprint release tag; default: the tag pinned in scaffold.json
43		SetValues  map[string]any
44		Files      []string
45		Force      bool
46		NoInput    bool
47		OutputJSON string // path to write CreateResult JSON; "-" means stdout
48		Stdin      io.Reader
49		Stdout     io.Writer
50		Stderr     io.Writer
51		HTTP       *http.Client
52		UserAgent  string
53	
54		// Test overrides. Production callers leave these zero-valued; the
55		// blueprint is fetched from the owner/repo recorded in scaffold.json.
56		Owner         string
57		Repo          string
58		GitHubBaseURL string
59	}
60	
61	// CreateResult is the machine-readable summary written when --output-json is
62	// set. Field names are stable and additive-only.
63	type CreateResult struct {
64		Blueprint string         `json:"blueprint"`
65		Owner     string         `json:"owner"`
66		Repo      string         `json:"repo"`
67		Version   string         `json:"version"`
68		OutputDir string         `json:"outputDir"`
69		Values    map[string]any `json:"values"`
70	}
71	
72	func (o *CreateOptions) applyDefaults() {
73		if o.StartDir == "" {
74			o.StartDir = "."
75		}
76		if o.Stdin == nil {
77			o.Stdin = os.Stdin
78		}
79		if o.UserAgent == "" {
80			o.UserAgent = "intropy-cli"
81		}
82	}
83	
84	// Create generates the deployment manifests: locate scaffold.json, download
85	// the pinned blueprint, load manifests/template.yaml, resolve values (seeded
86	// from the scaffold record, with optional interactive prompting), render
87	// manifests/skeleton into the output directory.
88	func Create(ctx context.Context, opts CreateOptions) error {
89		opts.applyDefaults()
90	
91		scaffold, projectRoot, err := blueprint.FindScaffold(opts.StartDir)
92		if err != nil {
93			if errors.Is(err, blueprint.ErrScaffoldNotFound) {
94				return fmt.Errorf("%w\nThis project was scaffolded before deployment metadata existed. Re-scaffold it with 'intropy int create', or commit a minimal %s:\n  {\"schemaVersion\":1,\"blueprint\":\"<blueprint>\",\"owner\":\"integrio-intropy\",\"repo\":\"intropy-blueprints\",\"version\":\"<tag>\",\"values\":{\"name\":\"<name>\"}}", err, blueprint.ScaffoldRelPath)
95			}
96			return err
97		}
98		if scaffold.SchemaVersion > blueprint.ScaffoldSchemaVersion {
99			return fmt.Errorf("%s has schemaVersion %d, but this CLI supports up to %d; upgrade intropy", blueprint.ScaffoldRelPath, scaffold.SchemaVersion, blueprint.ScaffoldSchemaVersion)
100		}
101		owner, repo := scaffold.Owner, scaffold.Repo
102		if opts.Owner != "" {
103			owner = opts.Owner
104		}
105		if opts.Repo != "" {
106			repo = opts.Repo
107		}
108	
109		tag := scaffold.Version
110		if opts.Version != "" {
111			tag = opts.Version
112		}
113		if tag == "" {
114			return fmt.Errorf("%s does not pin a blueprint version; pass --version", blueprint.ScaffoldRelPath)
115		}
116	
117		gh := blueprint.NewGitHubClient(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
118		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
119		blueprintRoot, cleanup, err := blueprint.DownloadBlueprint(ctx, gh, owner, repo, tag, scaffold.Blueprint, "intropy-manifests-*")
120		if err != nil {
121			return err
122		}
123		defer cleanup()
124	
125		manifestsRoot := filepath.Join(blueprintRoot, manifestDirName)
126		skelRoot := filepath.Join(manifestsRoot, skeletonDirName)
127		if !dirExists(skelRoot) || !fileExists(filepath.Join(manifestsRoot, templateManifestName)) {
128			return fmt.Errorf("blueprint %q at %s does not include deployment manifest templates (%s/); pass --version <newer tag> or update the blueprint", scaffold.Blueprint, tag, manifestDirName)
129		}
130	
131		tmpl, err := blueprint.LoadTemplate(filepath.Join(manifestsRoot, templateManifestName))
132		if err != nil {
133			return err
134		}
135		values, err := resolveManifestValues(tmpl, scaffold, opts)
136		if err != nil {
137			return err
138		}
139	
140		outputDir := opts.OutputDir
141		if outputDir == "" {
142			outputDir = filepath.Join(projectRoot, defaultOutputDirName)
143		}
144		if err := blueprint.EnsureOutputDir(outputDir, opts.Force); err != nil {
145			return err
146		}
147		if err := blueprint.Render(skelRoot, outputDir, values); err != nil {
148			return err
149		}
150		fmt.Fprintf(opts.Stderr, "wrote deployment manifests to %s (blueprint %s@%s)\n", outputDir, scaffold.Blueprint, tag)
151	
152		return maybeWriteCreateResult(opts, scaffold, owner, repo, tag, outputDir, values)
153	}
154	
155	// resolveManifestValues resolves the manifest template's parameters, seeded
156	// by the scaffold record: scaffold values whose names match declared
157	// parameters auto-fill (no re-prompt) but yield to --values/--set. The full
158	// scaffold value map is exposed under the reserved "scaffold" key — added
159	// after Resolve so it never contaminates JSON Schema validation.
160	func resolveManifestValues(tmpl *blueprint.Template, scaffold *blueprint.Scaffold, opts CreateOptions) (map[string]any, error) {
161		declared := map[string]bool{}
162		for _, f := range tmpl.Fields() {
163			if f.Name == scaffoldValuesKey {
164				return nil, fmt.Errorf("manifest template declares reserved parameter %q", scaffoldValuesKey)
165			}
166			declared[f.Name] = true
167		}
168		if _, ok := tmpl.Spec.Values[scaffoldValuesKey]; ok {
169			return nil, fmt.Errorf("manifest template declares reserved spec.values entry %q", scaffoldValuesKey)
170		}
171	
172		seed := map[string]any{}
173		for k, v := range scaffold.Values {
174			if declared[k] {
175				seed[k] = v
176			}
177		}
178	
179		prompter := blueprint.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
180		values, err := blueprint.ResolveLayered(tmpl, seed, opts.Files, opts.Stdin, opts.SetValues, prompter)
181		if err != nil {
182			return nil, err
183		}
184		values[scaffoldValuesKey] = scaffold.Values
185		return values, nil
186	}
187	
188	func maybeWriteCreateResult(opts CreateOptions, scaffold *blueprint.Scaffold, owner, repo, tag, outputDir string, values map[string]any) error {
189		if opts.OutputJSON == "" {
190			return nil
191		}
192		absOut, err := filepath.Abs(outputDir)
193		if err != nil {
194			absOut = outputDir
195		}
196		result := CreateResult{
197			Blueprint: scaffold.Blueprint,
198			Owner:     owner,
199			Repo:      repo,
200			Version:   tag,
201			OutputDir: absOut,
202			Values:    values,
203		}
204		data, err := json.MarshalIndent(result, "", "  ")
205		if err != nil {
206			return fmt.Errorf("write --output-json: %w", err)
207		}
208		data = append(data, '\n')
209		if opts.OutputJSON == "-" {
210			if _, err := opts.Stdout.Write(data); err != nil {
211				return fmt.Errorf("write --output-json: %w", err)
212			}
213			return nil
214		}
215		if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
216			return fmt.Errorf("write --output-json: %w", err)
217		}
218		return nil
219	}
220	
221	func dirExists(path string) bool {
222		info, err := os.Stat(path)
223		return err == nil && info.IsDir()
224	}
225	
226	func fileExists(path string) bool {
227		info, err := os.Stat(path)
228		return err == nil && !info.IsDir()
229	}
